[SysClientCacheDataMethodAttribute(true)]
public display PriceDiscJournalNum displayPriceDiscJournalNum()
{
    PriceDiscTable priceDiscTable = PriceDiscTable::findRecId(this.PriceDiscTableRecId);
    PriceDiscAdmTrans priceDiscAdmTrans = PriceDiscAdmTrans::findRecId(priceDiscTable.OriginalPriceDiscAdmTransRecId);
    return priceDiscAdmTrans.JournalNum;
}

/// <summary>
/// Find and format pricing attributes with related conditions
/// </summary>
/// <param name = "_pricingRuleRecId">Pricing rule reference</param>
/// <returns>Pricing attributes with related conditions</returns>
public GUPPricingAttributeDetailsPreview getPricingAttributeDetails(GUPPricingRuleRecId _pricingRuleRecId)
{
    return GUPPricingRule::getPricingAttributeDetails(_pricingRuleRecId);
}
